package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.net.Uri;import android.os.*;import android.text.InputFilter;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Optional library tools; the reader's primary navigation stays compact. */
public final class ToolsActivity extends Activity {
 final String hold="tools-"+UUID.randomUUID();static final int BIBLE=82,BIBLE_USX_FOLDER=89;AppPalette colors;LinearLayout content;WorkspaceBackupUi backup;RevisionNotebook revision;String page="home",bibleTitle="";AtomicBoolean importing;
 static void open(Context c,String page){c.startActivity(new Intent(c,ToolsActivity.class).putExtra("page",page));}
 static void revision(Context c,long subject,String title){c.startActivity(new Intent(c,ToolsActivity.class).putExtra("page","revision").putExtra("subject",subject).putExtra("revision_title",title));}
 protected void attachBaseContext(Context c){super.attachBaseContext(AppLanguage.wrap(c));}
 public void onCreate(Bundle state){super.onCreate(state);page=getIntent().getStringExtra("page");if(page==null)page="home";if(state!=null)bibleTitle=state.getString("bible_title","");backup=new WorkspaceBackupUi(this);revision=new RevisionNotebook(this,"",0,getIntent().getLongExtra("subject",0),getIntent().getStringExtra("revision_title")==null?AppLanguage.text(this,"Estudos"):getIntent().getStringExtra("revision_title"));revision.restore(state);render();}
 void render(){colors=AppPalette.of(this);getWindow().setStatusBarColor(colors.bg);getWindow().setNavigationBarColor(colors.bg);LinearLayout root=PlusUi.column(this);root.setBackgroundColor(colors.bg);root.setFitsSystemWindows(true);if(Build.VERSION.SDK_INT>=35){root.setFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(PlusUi.dp(this,12)+bars.left,PlusUi.dp(this,6)+bars.top,PlusUi.dp(this,12)+bars.right,PlusUi.dp(this,6)+bars.bottom);return insets;});}LinearLayout head=new LinearLayout(this);View back=PlusUi.backButton(this,colors,this::finish);LinearLayout.LayoutParams backParams=new LinearLayout.LayoutParams(PlusUi.dp(this,44),PlusUi.dp(this,44));backParams.rightMargin=PlusUi.dp(this,12);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(PlusUi.dp(this,12),PlusUi.dp(this,8),PlusUi.dp(this,12),PlusUi.dp(this,4));head.addView(back,backParams);TextView title=PlusUi.text(this,"Ferramentas",23);title.setTypeface(AppFonts.title(this,23));head.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);ScrollView scroll=new ScrollView(this);content=PlusUi.column(this);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView signature=PlusUi.text(this,"Haidoy Carlos Mautempo",10);signature.setGravity(Gravity.CENTER);root.addView(signature);setContentView(root);section("Biblioteca");action("tasks","Tarefas em segundo plano",()->TaskService.open(this));action("import","Pastas de importação",()->ImportWork.folders(this));action("search","Pesquisar no conteúdo",()->LibrarySearchActivity.open(this));action("collection","Colecções",()->BookCategories.manage(this,()->{}));action("book","Bíblias importadas",this::bibles);section("Leitura e voz");action("speaker","Vozes naturais do Google",()->NaturalVoicesActivity.open(this));action("tune","Detectar motores TTS",()->VoiceEnginesActivity.open(this));action("book","Consultar passagem bíblica",()->BibleLinks.query(this));action("widget","Adicionar widget de leitura",()->ReadingWidget.pin(this));action("android","Instalar aplicação Android",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(ApkInstallActivity.MIME),94);}catch(Exception e){PlusUi.error(this,e);}});action("speed","Desempenho",()->PlusUi.performance(this));action("dictionary","Dicionário de pronúncia",()->PlusUi.dictionary(this));action("scan","Dados de OCR",this::ocr);section("Estudos e cópias");action("storage","Armazenamento",()->StorageActivity.open(this));action("pdfbook","Caderno de revisão em PDF",revision::choose);action("restore","Cópia e recuperação",backup::show);action("shield","Licenças",this::licenses);if(page.equals("bibles")){page="home";bibles();}else if(page.equals("backup")){page="home";backup.show();}else if(page.equals("revision")){page="home";revision.choose();}}
 TextView button(String text,Runnable task){TextView b=PlusUi.text(this,text,15);b.setTextColor(colors.accent);b.setGravity(Gravity.CENTER);b.setMinHeight(PlusUi.dp(this,48));b.setOnClickListener(v->task.run());return b;}
 void section(String title){TextView label=PlusUi.text(this,title,12);label.setTextColor(colors.muted);label.setPadding(0,PlusUi.dp(this,14),0,PlusUi.dp(this,8));content.addView(label);}
 void action(String icon,String title,Runnable task){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(PlusUi.dp(this,13),PlusUi.dp(this,10),PlusUi.dp(this,10),PlusUi.dp(this,10));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(colors.surface);bg.setCornerRadius(PlusUi.dp(this,16));bg.setStroke(PlusUi.dp(this,1),colors.line);row.setBackground(bg);row.addView(PlusUi.iconTile(this,icon,colors),new LinearLayout.LayoutParams(PlusUi.dp(this,40),PlusUi.dp(this,40)));TextView label=PlusUi.text(this,title,15);label.setGravity(Gravity.CENTER_VERTICAL);label.setPadding(PlusUi.dp(this,13),0,PlusUi.dp(this,6),0);row.addView(label,new LinearLayout.LayoutParams(0,PlusUi.dp(this,44),1));row.addView(new Icons(this,"chevron",colors.muted),new LinearLayout.LayoutParams(PlusUi.dp(this,18),PlusUi.dp(this,24)));row.setContentDescription(AppLanguage.text(this,title));row.setOnClickListener(v->task.run());Motion.touch(row);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=PlusUi.dp(this,10);content.addView(row,p);}
 void bibles(){PlusUi.run(this,()->{List<StudyStore.Row> rows;try(PlusStore db=new PlusStore(this)){rows=db.rows("bible_sources",null,null,"title COLLATE NOCASE",1000);}PlusUi.post(this,()->{UiPanel panel=new UiPanel(this,"Bíblias importadas",null,"book");panel.action("add","Importar ficheiro bíblico","MyBible SQLite3, USX, ZIP, TXT ou livro",false,this::pickBible);panel.action("import","Importar pasta USX","Uma versão, incluindo subpastas como USX_1",false,this::pickUsxFolder);panel.action("book","Almeida · ACF / ARA","Importar a sua edição",false,()->new UiDialog.Builder(this).setTitle("Almeida").setItems(new String[]{"ACF","ARA"},(d,n)->pickBible(n==0?"ACF":"ARA")).show());panel.action("book","Bíblia Amplificada","Importar a sua edição",false,()->pickBible("Bíblia Amplificada"));panel.action("book","A Mensagem","Importar a sua edição",false,()->pickBible("A Mensagem"));panel.action("book","Usar Bíblia da biblioteca",null,false,()->BibleWork.library(this));panel.action("search","Consultar passagem bíblica",null,false,()->BibleLinks.query(this));panel.action("info","Formato de importação",null,false,()->new UiDialog.Builder(this).setTitle("Formatos de Bíblia").setMessage("MyBible: seleccione o módulo .SQLite3 (por exemplo ARAi+.SQLite3 ou ARM’67.SQLite3), mesmo que o Android o mostre como BIN. Ficheiros .search são índices; .commentaries, .dictionary e .plan não são texto bíblico.\n\nUSX: pode importar um livro .usx, um ZIP com uma versão ou escolher a pasta da versão/USX_1. Ficheiros styles.xml, LDML, VRS e JPG são auxiliares e ficam de fora. Escolha uma só versão de cada vez.\n\nMantém TXT, CSV, TSV, USFM, EPUB, PDF e DOCX com texto, incluindo UTF-8, UTF-16 com BOM e Windows-1252. Os textos integrais das traduções não acompanham o aplicativo.").setPositiveButton("Fechar",null).show());for(StudyStore.Row row:rows)panel.action("book",row.s("title"),null,false,()->bibleMenu(row));panel.show();});});}
 void pickBible(){pickBible("");}
 void pickBible(String edition){if(importing!=null){PlusUi.toast(this,"Aguarde a importação actual.");return;}EditText title=PlusUi.input(this,"Nome da tradução",edition.isEmpty()?"Minha Bíblia":edition,120);new UiDialog.Builder(this).setTitle("Importar Bíblia").setView(title).setPositiveButton("Escolher ficheiro",(d,w)->{bibleTitle=title.getText().toString().trim();if(bibleTitle.isEmpty())bibleTitle="Minha Bíblia";try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),BIBLE);}catch(Exception e){PlusUi.error(this,e);}}).setNegativeButton("Cancelar",null).show();}
 void pickUsxFolder(){EditText title=PlusUi.input(this,"Nome da tradução","Minha Bíblia USX",120);new UiDialog.Builder(this).setTitle("Importar pasta USX").setMessage("Escolha a pasta de uma versão, como nbv_usx ou release/USX_1. Pode incluir subpastas. Capas e configurações são ignoradas.").setView(title).setPositiveButton("Escolher pasta",(d,w)->{bibleTitle=title.getText().toString().trim();if(bibleTitle.isEmpty())bibleTitle="Minha Bíblia USX";try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),BIBLE_USX_FOLDER);}catch(Exception e){PlusUi.error(this,e);}}).setNegativeButton("Cancelar",null).show();}
 void importBible(Uri uri){BibleWork.enqueue(this,uri,bibleTitle.isEmpty()?"Minha Bíblia":bibleTitle,Intent.FLAG_GRANT_READ_URI_PERMISSION);}
 void bibleMenu(StudyStore.Row source){UiPanel panel=new UiPanel(this,source.s("title"),null,"book");panel.action("search","Abrir passagem",null,false,()->{EditText input=PlusUi.input(this,"Livro capítulo:versículo","",120);new UiDialog.Builder(this).setTitle("Passagem bíblica").setView(input).setPositiveButton("Abrir",(d,w)->{List<BibleReferences.Reference> refs=BibleReferences.references(input.getText().toString());if(refs.isEmpty())PlusUi.toast(this,"Indique o livro, capítulo e versículo.");else BibleLinks.passage(this,source,refs.get(0));}).setNegativeButton("Cancelar",null).show();});panel.danger("Eliminar esta Bíblia",()->new UiDialog.Builder(this).setTitle("Eliminar a Bíblia importada?").setMessage("O ficheiro original continua na sua pasta.").setPositiveButton("Eliminar",(d,w)->PlusUi.run(this,()->{try(PlusStore db=new PlusStore(this)){db.getWritableDatabase().beginTransaction();try{db.getWritableDatabase().delete("bible_verses","source=?",new String[]{""+source.id()});db.getWritableDatabase().delete("bible_sources","id=?",new String[]{""+source.id()});db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}}PlusUi.post(this,this::bibles);})).setNegativeButton("Cancelar",null).show());panel.show();}
 void ocr(){new UiDialog.Builder(this).setTitle("Dados de OCR").setItems(new String[]{"Português · cerca de 2 MB","English · cerca de 4 MB"},(d,n)->{String language=n==1?"eng":"por";UiPanel panel=new UiPanel(this,"Dados de OCR",n==1?"English":"Português","scan");panel.action("download",OcrEngine.model(this,language).isFile()?"Verificar dados":"Descarregar dados",null,false,()->OcrWork.model(this,language));if(OcrEngine.model(this,language).isFile())panel.danger("Eliminar dados descarregados",()->new UiDialog.Builder(this).setTitle("Eliminar dados de OCR?").setMessage("O texto já reconhecido é conservado.").setPositiveButton("Eliminar",(x,w)->{if(OcrWork.modelsBusy()){PlusUi.toast(this,"Aguarde o OCR terminar.");return;}OcrEngine.model(this,language).delete();PlusUi.toast(this,"Dados removidos. O texto já reconhecido foi conservado.");}).setNegativeButton("Cancelar",null).show());panel.show();}).setNegativeButton("Fechar",null).show();}
 void licenses(){PlusUi.run(this,()->{String notice;try(InputStream in=getAssets().open("licenses/NOTICE.txt")){notice=new String(ContentText.read(in,200000),StandardCharsets.UTF_8);}final String value=notice;PlusUi.post(this,()->new UiDialog.Builder(this).setTitle("Licenças").setMessage(value).setPositiveButton("Fechar",null).show());});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);backup.result(request,result,data);revision.result(request,result,data);if(result==RESULT_OK&&data!=null&&data.getData()!=null){if(request==BIBLE_USX_FOLDER){BibleModuleWork.folder(this,data.getData(),bibleTitle.isEmpty()?"Minha Bíblia USX":bibleTitle,data.getFlags());}else if(request==BIBLE){ImportWork.permission(this,data.getData(),data.getFlags());importBible(data.getData());}else if(request==94)ApkInstallActivity.open(this,data.getData(),"Aplicação.apk");}}
 protected void onSaveInstanceState(Bundle state){state.putString("bible_title",bibleTitle);revision.save(state);super.onSaveInstanceState(state);}
 protected void onStart(){super.onStart();QuickSearchService.holdOverlay(hold,true);UiDialog.visibility(this,true);UiPanel.visibility(this,true);}protected void onStop(){QuickSearchService.holdOverlay(hold,false);UiDialog.visibility(this,false);UiPanel.visibility(this,false);super.onStop();}
 protected void onDestroy(){QuickSearchService.holdOverlay(hold,false);if(importing!=null)importing.set(true);backup.close();UiDialog.dismissAll(this);UiPanel.dismissAll(this);super.onDestroy();}
}
